// Call the target function to obtain a const, non-owning C-string pointer
const char *ver = goldleaf_compat::version();

// Do not modify or free the returned pointer; ownership is not transferred.
// We must return a non-null output object, so allocate storage for a const char *
// and store the returned pointer in it. The stored pointer may legally be null.
const char **version_ptr = new const char *;
*version_ptr = ver;

// Track whether the returned pointer was null; downstream stubs can use this.
FUZZ_SET_ATTR_INT(version_ptr, "maybe_null", ver ? 0 : 1);

// Validation summary:
// - We never modify or free the returned C-string (const correctness preserved).
// - We return a persistent const char ** object that may reference a null pointer.

// Generate a random a and a b that guarantees no signed int overflow on addition.
int a = *FUZZ_PARAM(int);
unsigned int r = *FUZZ_PARAM(unsigned int);

// Constrain b so that (long long)a + b remains within 32-bit signed range.
long long minI = -2147483648LL;
long long maxI =  2147483647LL;
long long a64 = (long long)a;

// Keep the search window small for performance while still exploring negatives/positives.
long long low = minI - a64;  // minimum b to avoid underflow
long long high = maxI - a64; // maximum b to avoid overflow
if (low < -1000000LL) low = -1000000LL;
if (high > 1000000LL) high = 1000000LL;
if (low > high) { FUZZ_BAIL(); }
long long span = (high - low + 1);
long long b64 = low + (long long)(r % (unsigned long long)span);
int b = (int)b64;

// Invoke the target function
int sum = goldleaf_compat::add(a, b);

// Property: since we constrained inputs, the result must equal a + b in 64-bit space
long long expected = a64 + (long long)b;
FUZZ_ASSERT((long long)sum == expected, "goldleaf_compat::add must compute exact a+b without overflow");

